package vn.svframe.svframelib.player.particle.type;
import vn.svframe.svframelib.player.particle.*;import vn.svframe.svframelib.util.configobject.ConfigObject;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.Vec3d;import java.util.Map;
public class GalaxyParticleEffect extends ParticleEffect{private final double speed,height,rSpeed,yCoord;private final int amount;private double a;public GalaxyParticleEffect(String k,Map<String,Double>m,ParticleInformation p){super(k,p);speed=resolveModifier(m,"speed")*.2;height=resolveModifier(m,"height");rSpeed=resolveModifier(m,"rotation-speed");yCoord=resolveModifier(m,"y-coord");amount=(int)resolveModifier(m,"amount");}public GalaxyParticleEffect(ConfigObject o){super(o);speed=o.getDouble("speed")*.2;height=o.getDouble("height");rSpeed=o.getDouble("rotation-speed");yCoord=o.getDouble("y-coord");amount=o.getInt("amount");}public ParticleEffectType getType(){return ParticleEffectType.GALAXY;}public void tick(){ServerPlayerEntity pl=playerData.getPlayer();Vec3d b=pl.getPos().add(0,height,0);int n=Math.max(1,amount);for(int k=0;k<n;k++){double x=a+Math.PI*2*k/n;particle.display(pl.getServerWorld(),b,0,Math.cos(x),yCoord,Math.sin(x),speed);}a+=Math.PI/24*rSpeed;if(a>Math.PI*2)a-=Math.PI*2;}}
